  2288    TT_Set_MM_Blend( TT_Face    face,
  2289                     FT_UInt    num_coords,
  2290                     FT_Fixed*  coords )
  2291    {
  2292      FT_Error    error = FT_Err_Ok;
  2293      GX_Blend    blend;
  2294      FT_MM_Var*  mmvar;
  2295      FT_UInt     i, j;
  2296      FT_Bool     is_default_instance = 1;
  2297      FT_Memory   memory = face->root.memory;
  2298
  2299      enum
  2300      {
  2301        mcvt_retain,
  2302        mcvt_modify,
  2303        mcvt_load
  2304
  2305      } manageCvt;
  2306
  2307
  2308      face->doblend = FALSE;
  2309
  2310      if ( !face->blend )
  2311      {
  2312        if ( FT_SET_ERROR( TT_Get_MM_Var( face, NULL ) ) )
  2313          goto Exit;
  2314      }
  2315
  2316      blend = face->blend;
  2317      mmvar = blend->mmvar;
  2318
  2319      if ( num_coords > mmvar->num_axis )
  2320      {
  2321        FT_TRACE2(( "TT_Set_MM_Blend: only using first %d of %d coordinates\n",
  2322                    mmvar->num_axis, num_coords ));
  2323        num_coords = mmvar->num_axis;
  2324      }
  2325
  2326      FT_TRACE5(( "normalized design coordinates:\n" ));
  2327
  2328      for ( i = 0; i < num_coords; i++ )
  2329      {
  2330        FT_TRACE5(( "  %.5f\n", coords[i] / 65536.0 ));
  2331        if ( coords[i] < -0x00010000L || coords[i] > 0x00010000L )
  2332        {
  2333          FT_TRACE1(( "TT_Set_MM_Blend: normalized design coordinate %.5f\n"
  2334                      "                 is out of range [-1;1]\n",
  2335                      coords[i] / 65536.0 ));
  2336          error = FT_THROW( Invalid_Argument );
  2337          goto Exit;
  2338        }
  2339
  2340        if ( coords[i] != 0 )
  2341          is_default_instance = 0;
  2342      }
  2343
  2344      FT_TRACE5(( "\n" ));
  2345
  2346      if ( !face->is_cff2 && !blend->glyphoffsets )
  2347        if ( FT_SET_ERROR( ft_var_load_gvar( face ) ) )
  2348          goto Exit;
  2349
  2350      if ( !blend->normalizedcoords )
  2351      {
  2352        if ( FT_NEW_ARRAY( blend->normalizedcoords, mmvar->num_axis ) )
  2353          goto Exit;
  2354
  2355        manageCvt = mcvt_modify;
  2356
  2357        /* If we have not set the blend coordinates before this, then the  */
  2358        /* cvt table will still be what we read from the `cvt ' table and  */
  2359        /* we don't need to reload it.  We may need to change it though... */
  2360      }
  2361      else
  2362      {
  2363        manageCvt = mcvt_retain;
  2364
  2365        for ( i = 0; i < num_coords; i++ )
  2366        {
  2367          if ( blend->normalizedcoords[i] != coords[i] )
  2368          {
  2369            manageCvt = mcvt_load;
  2370            break;
  2371          }
  2372        }
  2373
  2374        for ( ; i < mmvar->num_axis; i++ )
  2375        {
  2376          if ( blend->normalizedcoords[i] != 0 )
  2377          {
  2378            manageCvt = mcvt_load;
  2379            break;
  2380          }
  2381        }
  2382
  2383        /* If we don't change the blend coords then we don't need to do  */
  2384        /* anything to the cvt table.  It will be correct.  Otherwise we */
  2385        /* no longer have the original cvt (it was modified when we set  */
  2386        /* the blend last time), so we must reload and then modify it.   */
  2387      }
  2388
  2389      blend->num_axis = mmvar->num_axis;
  2390      FT_MEM_COPY( blend->normalizedcoords,
  2391                   coords,
  2392                   num_coords * sizeof ( FT_Fixed ) );
  2393
  2394      face->doblend = TRUE;
  2395
  2396      if ( face->cvt )
  2397      {
  2398        switch ( manageCvt )
  2399        {
  2400        case mcvt_load:
  2401          /* The cvt table has been loaded already; every time we change the */
  2402          /* blend we may need to reload and remodify the cvt table.         */
  2403          FT_FREE( face->cvt );
  2404          face->cvt = NULL;
  2405
  2406          error = tt_face_load_cvt( face, face->root.stream );
  2407          break;
  2408
  2409        case mcvt_modify:
  2410          /* The original cvt table is in memory.  All we need to do is */
  2411          /* apply the `cvar' table (if any).                           */
  2412          error = tt_face_vary_cvt( face, face->root.stream );
  2413          break;
  2414
  2415        case mcvt_retain:
  2416          /* The cvt table is correct for this set of coordinates. */
  2417          break;
  2418        }
  2419      }
  2420
  2421      /* check whether the current variation tuple coincides */
  2422      /* with a named instance                               */
  2423
  2424      for ( i = 0; i < blend->mmvar->num_namedstyles; i++ )
  2425      {
  2426        FT_Fixed*  nsc = blend->normalized_stylecoords + i * blend->num_axis;
  2427        FT_Fixed*  ns  = blend->normalizedcoords;
  2428
  2429
  2430        for ( j = 0; j < blend->num_axis; j++, nsc++, ns++ )
  2431        {
  2432          if ( *nsc != *ns )
  2433            break;
  2434        }
  2435
  2436        if ( j == blend->num_axis )
  2437          break;
  2438      }
  2439
  2440      /* adjust named instance index */
  2441      face->root.face_index &= 0xFFFF;
  2442      if ( i < blend->mmvar->num_namedstyles )
  2443        face->root.face_index |= ( i + 1 ) << 16;
  2444
  2445      face->is_default_instance = is_default_instance;
  2446
  2447    Exit:
  2448      return error;
  2449    }
